import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, smoothstep, oneMinus, mul } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Color } = ctx.THREE;

  const root = new Group();

  // --------------------------------------------------------------------
  // 1. Gradient Backdrop (vertical fade)
  // --------------------------------------------------------------------
  const backdropW = 7.0;
  const backdropH = 6.0;
  const backdropGeom = new PlaneGeometry(backdropW, backdropH);
  const backdropMat = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'),
    transparent: true,
    side: ctx.THREE.DoubleSide,
  });

  const uvNode = uv();
  const fadeTop = smoothstep(0.0, 0.09, uvNode.y);
  const fadeBottom = oneMinus(smoothstep(0.91, 1.0, uvNode.y));
  backdropMat.opacityNode = mul(fadeTop, fadeBottom);

  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // --------------------------------------------------------------------
  // 2. Ribbon Plane
  // --------------------------------------------------------------------
  const ribbonW = 7.0;
  const ribbonH = 0.35;
  const ribbonGeom = new PlaneGeometry(ribbonW, ribbonH);
  const ribbonMat = new MeshStandardNodeMaterial({
    color: new Color('#111117'),
    roughness: 0.6,
    metalness: 0.2,
    side: ctx.THREE.DoubleSide,
    transparent: true,
  });
  const ribbon = new Mesh(ribbonGeom, ribbonMat);
  ribbon.position.set(0, 0, 0);
  root.add(ribbon);

  // --------------------------------------------------------------------
  // 3. Top / Bottom Hairlines (flat, unlit)
  // --------------------------------------------------------------------
  const hairH = 0.006;
  const hairGeom = new PlaneGeometry(ribbonW, hairH);
  const hairMat = new MeshBasicNodeMaterial({
    color: new Color('#23232b'),
    side: ctx.THREE.DoubleSide,
  });

  const topHair = new Mesh(hairGeom, hairMat);
  topHair.position.set(0, ribbonH / 2 - hairH / 2, 0.001);
  const bottomHair = new Mesh(hairGeom, hairMat);
  bottomHair.position.set(0, -ribbonH / 2 + hairH / 2, 0.001);
  root.add(topHair, bottomHair);

  // --------------------------------------------------------------------
  // 4. Ticker Content (scrolling)
  // --------------------------------------------------------------------
  const scrollGroup = new Group();
  scrollGroup.position.z = 0.02; // lift above ribbon
  root.add(scrollGroup);

  const textOpts = {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
    letterSpacing: 0.06,
  };

  const tickerItems = [
    'CAL NA-01 BEAT 28800 VPH',
    'POWER RESERVE 72H',
    'CASE 40.5 MM 904L',
    'REF 5811 IN STOCK',
    'WAITLIST 1204',
    'NEXT FITTING JUL 18',
  ];

  const gapSide = 0.5; // 0.5‑unit gap on each side of a tick or text block
  const tickW = 0.02;
  const tickH = 0.14;
  const tickDepth = 0.001;
  const tickGeom = new BoxGeometry(tickW, tickH, tickDepth);
  const tickMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.5,
    metalness: 0,
    roughness: 0,
    side: ctx.THREE.DoubleSide,
    transparent: true,
  });
  const createTick = () => new Mesh(tickGeom, tickMat);

  // approximate character width for mono 13pt at scene scale
  const charW = 0.08;

  // start cursor at left edge of ribbon
  let cursor = -ribbonW / 2;

  const addEntry = (txt) => {
    // left gap before left tick
    cursor += gapSide;

    // left tick
    const leftTick = createTick();
    leftTick.position.set(cursor + tickW / 2, 0, 0);
    scrollGroup.add(leftTick);
    cursor += tickW;

    // gap after left tick
    cursor += gapSide;

    // text
    const txtObj = ctx.fontAtlas.createText(txt, textOpts);
    const txtW = txt.length * charW;
    txtObj.position.set(cursor + txtW / 2, 0, 0);
    scrollGroup.add(txtObj);
    cursor += txtW;

    // gap before right tick
    cursor += gapSide;

    // right tick
    const rightTick = createTick();
    rightTick.position.set(cursor + tickW / 2, 0, 0);
    scrollGroup.add(rightTick);
    cursor += tickW;

    // right gap after right tick
    cursor += gapSide;
  };

  tickerItems.forEach(addEntry);

  // total length of one content strip
  const totalSpan = cursor - (-ribbonW / 2);

  // duplicate for seamless looping
  const duplicate = scrollGroup.clone();
  duplicate.position.x = totalSpan;
  root.add(duplicate);

  // --------------------------------------------------------------------
  // 5. Apply cinematic primitives (fly-through) to scrolling container
  // --------------------------------------------------------------------
  const primitives = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const res = fn(scrollGroup, prim.params);
        primitives.push(res);
      }
    }
  }

  // --------------------------------------------------------------------
  // 6. Cleanup
  // --------------------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose geometries & materials
    backdropGeom.dispose();
    backdropMat.dispose();
    ribbonGeom.dispose();
    ribbonMat.dispose();
    hairGeom.dispose();
    hairMat.dispose();
    tickGeom.dispose();
    tickMat.dispose();

    // Dispose any text geometries (fontAtlas may own resources)
    scrollGroup.traverse((obj) => {
      if (obj.isMesh && obj.geometry) obj.geometry.dispose();
    });
    duplicate.traverse((obj) => {
      if (obj.isMesh && obj.geometry) obj.geometry.dispose();
    });

    // Clear GSAP timelines
    gsap.globalTimeline.clear();

    // Cleanup primitives
    primitives.forEach((p) => {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    });

    // Remove from parent
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
